const mode = process.env.MOE_MIGRATION_DRILL;
const service = "/repository/migrations/migration-service.ts";
const receipt = "/repository/migrations/migration-receipt.ts";
const ports = "/repository/migrations/migration-ports.ts";
const swaps = {
 order: [service, "await ports.dump(input.databaseUrl, path);\n    backupRef = \x60\x24{path}@sha256:\x24{await backupFileHash(path)}\x60;\n    const applied = await ports.apply(input.workspace, input.databaseUrl);",
 "const applied = await ports.apply(input.workspace, input.databaseUrl);\n    await ports.dump(input.databaseUrl, path);\n    backupRef = \x60\x24{path}@sha256:\x24{await backupFileHash(path)}\x60;"],
 backup: [service, "} catch (error) {\n    if (backupRef", "} catch (error) {\n    if (backupRef === null) await ports.apply(input.workspace, input.databaseUrl);\n    if (backupRef"],
 pairing: [receipt, "(refusal !== null || v.backupRef === null)", "(v.backupRef === null)"],
 filename: [ports, 'this.file = migrationFilename(file) ? file : "MIGRATION_FILE_UNKNOWN";', 'this.file = "MIGRATION_FILE_UNKNOWN";'],
 code: [receipt, "Object.freeze({ code, layer: codeLayers[code], detail })", 'Object.freeze({ code: "MIGRATION_FAILED", layer: codeLayers[code], detail })'],
 layer: [receipt, 'MIGRATION_BACKUP_FAILED: "DAEMON_INGRESS"', 'MIGRATION_BACKUP_FAILED: "LEDGER"'],
 busy: [service, 'throw migrationError(existsSync(lock) ? "MIGRATION_IN_PROGRESS" : "MIGRATION_BACKUP_FAILED");',
 'return recordMigrationReceipt(store, base);'],
 corrupt: [ports, "dump: nodeBackupPorts().database", 'dump: async (url, path) => { await nodeBackupPorts().database(url, path); await (await import("node:fs/promises")).appendFile(path, "\\nSELECT * FROM missing_restore_table;\\n"); }'],
};
if (!Object.hasOwn(swaps, mode)) throw new Error("DRILL_MODE_UNKNOWN");
const [suffix, before, after] = swaps[mode];
export default {
 test: { fileParallelism: false, maxWorkers: 1, testTimeout: 30000 },
 plugins: [{ name: "production-mutation", enforce: "pre", transform(code, id) {
   if (!id.replaceAll("\\", "/").split("?")[0].endsWith(suffix)) return;
   if (code.split(before).length !== 2) throw new Error("DRILL_ANCHOR_NOT_EXACTLY_ONE");
   process.stdout.write("DRILL_APPLIED:" + mode + "\n");
   return { code: code.replace(before, after), map: null };
 } }],
};
